        for k in expired:
            del self._items[k]
        while len(self._items) > self._capacity:
            self._items.popitem(last=False)

    def get(self, key, now, default=None):
        item = self._items.get(key)
        if item is None:
            return default
        value, expires = item
        if now >= expires:
            del self._items[key]
            return default
        self._items.move_to_end(key)
        return value

